  1→import * as os from "node:os";
  2→import * as path from "node:path";
  3→import * as clack from "@clack/prompts";
  4→import type { Config } from "../config/config.js";
  5→import type { ConfiguredChannelAction, ChannelId, ChannelStatus } from "./types.js";
  6→import { CHANNEL_META } from "./types.js";
  7→import { guardCancel, ok, c } from "./helpers.js";
  8→
  9→export function getChannelStatuses(config: Config): ChannelStatus[] {
 10→  const statuses: ChannelStatus[] = [];
 11→
 12→  for (const [id, meta] of Object.entries(CHANNEL_META) as [ChannelId, typeof CHANNEL_META[ChannelId]][]) {
 13→    const ch = config.channels[id] as Record<string, unknown> | undefined;
 14→    const enabled = ch?.enabled === true;
 15→    const configured = !!ch && Object.keys(ch).length > 1;
 16→
 17→    let hint: string | undefined;
 18→    if (id === "telegram" && ch?.botToken && typeof ch.botToken === "string" && ch.botToken !== "YOUR_BOT_TOKEN_HERE") {
 19→      hint = `Chat ID: ${ch.chatId}`;
 20→    }
 21→    if (id === "discord" && ch?.guildId) {
 22→      hint = `Guild: ${ch.guildId}`;
 23→    }
 24→
 25→    statuses.push({ id, label: meta.label, configured, enabled, hint });
 26→  }
 27→
 28→  return statuses;
 29→}
 30→
 31→export function noteChannelStatus(config: Config): void {
 32→  const statuses = getChannelStatuses(config);
 33→  const lines = statuses.map((s) => {
 34→    const status = s.enabled ? "enabled" : s.configured ? "disabled" : "not configured";
 35→    const hintStr = s.hint ? ` — ${s.hint}` : "";
 36→    return `  ${s.label}: ${status}${hintStr}`;
 37→  });
 38→
 39→  console.log("");
 40→  console.log(`${c.bold}  Channel status${c.reset}`);
 41→  for (const line of lines) console.log(line);
 42→  console.log("");
 43→}
 44→
 45→async function promptConfiguredAction(label: string): Promise<ConfiguredChannelAction> {
 46→  return guardCancel(
 47→    await clack.select({
 48→      message: `${label} already configured. What do you want to do?`,
 49→      options: [
 50→        { value: "modify" as const, label: "Modify settings" },
 51→        { value: "disable" as const, label: "Disable bot" },
 52→        { value: "delete" as const, label: "Delete config" },
 53→        { value: "skip" as const, label: "Skip (leave as-is)" },
 54→      ],
 55→      initialValue: "modify" as const,
 56→    }),
 57→  );
 58→}
 59→
 60→async function configureViaPlugin(channelId: ChannelId): Promise<void> {
 61→  const pluginImports: Record<ChannelId, () => Promise<any>> = {
 62→    telegram: () => import('../../plugins/telegram/index.js'),
 63→    discord: async () => {
 64→      const pkg = '@openacp/plugin-discord';
 65→      try {
 66→        return await import(/* webpackIgnore: true */ pkg);
 67→      } catch {
 68→        throw new Error(
 69→          `${pkg} is not installed. Run: openacp plugin add ${pkg}`,
 70→        );
 71→      }
 72→    },
 73→  };
 74→
 75→  const importer = pluginImports[channelId];
 76→  if (!importer) return;
 77→
 78→  const { SettingsManager } = await import('../plugin/settings-manager.js');
 79→  const { createInstallContext } = await import('../plugin/install-context.js');
 80→  const basePath = path.join(os.homedir(), '.openacp', 'plugins');
 81→  const settingsManager = new SettingsManager(basePath);
 82→
 83→  const pluginModule = await importer();
 84→  const plugin = pluginModule.default;
 85→
 86→  if (plugin?.configure) {
 87→    const ctx = createInstallContext({
 88→      pluginName: plugin.name,
 89→      settingsManager,
 90→      basePath,
 91→    });
 92→    await plugin.configure(ctx);
 93→  }
 94→}
 95→
 96→export async function configureChannels(config: Config): Promise<{ config: Config; changed: boolean }> {
 97→  const next = structuredClone(config);
 98→  let changed = false;
 99→
100→  noteChannelStatus(next);
101→
102→  while (true) {
103→    const statuses = getChannelStatuses(next);
104→    const options = statuses.map((s) => {
105→      const status = s.enabled ? "enabled" : s.configured ? "disabled" : "not configured";
106→      return {
107→        value: s.id,
108→        label: `${s.label} (${CHANNEL_META[s.id].method})`,
109→        hint: status + (s.hint ? ` · ${s.hint}` : ""),
110→      };
111→    });
112→
113→    const choice = guardCancel(
114→      await clack.select({
115→        message: "Select a channel",
116→        options: [
117→          ...options,
118→          { value: "__done__" as const, label: "Finished" },
119→        ],
120→      }),
121→    );
122→
123→    if (choice === "__done__") break;
124→
125→    const channelId = choice as ChannelId;
126→    const meta = CHANNEL_META[channelId];
127→    const existing = next.channels[channelId] as Record<string, unknown> | undefined;
128→    const isConfigured = !!existing && Object.keys(existing).length > 1;
129→
130→    if (isConfigured) {
131→      const action = await promptConfiguredAction(meta.label);
132→
133→      if (action === "skip") continue;
134→      if (action === "disable") {
135→        (next.channels[channelId] as Record<string, unknown>).enabled = false;
136→        changed = true;
137→        console.log(ok(`${meta.label} disabled`));
138→        continue;
139→      }
140→      if (action === "delete") {
141→        const confirmed = guardCancel(
142→          await clack.confirm({
143→            message: `Delete ${meta.label} config? This cannot be undone.`,
144→            initialValue: false,
145→          }),
146→        );
147→        if (confirmed) {
148→          delete next.channels[channelId];
149→          changed = true;
150→          console.log(ok(`${meta.label} config deleted`));
151→        }
152→        continue;
153→      }
154→      // action === "modify" — fall through to plugin configure
155→    }
156→
157→    // Run channel configuration via plugin configure()
158→    await configureViaPlugin(channelId);
159→    changed = true;
160→  }
161→
162→  return { config: next, changed };
163→}
