  1→import { resolveLoadOrder } from './plugin-loader.js'
  2→import { ServiceRegistry } from './service-registry.js'
  3→import { MiddlewareChain } from './middleware-chain.js'
  4→import { ErrorTracker } from './error-tracker.js'
  5→import { createPluginContext } from './plugin-context.js'
  6→import type { OpenACPPlugin, EventBus, Logger, MigrateContext } from './types.js'
  7→import type { SettingsManager } from './settings-manager.js'
  8→import type { PluginRegistry } from './plugin-registry.js'
  9→
 10→const SETUP_TIMEOUT_MS = 30_000
 11→const TEARDOWN_TIMEOUT_MS = 10_000
 12→
 13→function withTimeout<T>(promise: Promise<T>, ms: number, label: string): Promise<T> {
 14→  return new Promise<T>((resolve, reject) => {
 15→    const timer = setTimeout(() => reject(new Error(`Timeout: ${label} exceeded ${ms}ms`)), ms)
 16→    if (typeof timer === 'object' && timer !== null && 'unref' in timer) {
 17→      ;(timer as NodeJS.Timeout).unref()
 18→    }
 19→    promise.then(resolve, reject).finally(() => clearTimeout(timer))
 20→  })
 21→}
 22→
 23→function resolvePluginConfig(pluginName: string, configManager: unknown): Record<string, unknown> {
 24→  try {
 25→    const allConfig = (configManager as any)?.get?.() ?? {}
 26→    // Try new format: plugins.builtin['@openacp/speech'].config
 27→    const pluginEntry = allConfig.plugins?.builtin?.[pluginName]
 28→    if (pluginEntry?.config && Object.keys(pluginEntry.config).length > 0) {
 29→      return pluginEntry.config
 30→    }
 31→    // @deprecated Legacy config path mapping — kept for backward compat with pre-plugin configs.
 32→    // New plugins should use plugins.builtin['<name>'].config format. Remove when all users have migrated.
 33→    const legacyMap: Record<string, string> = {
 34→      '@openacp/security': 'security',
 35→      '@openacp/speech': 'speech',
 36→      '@openacp/tunnel': 'tunnel',
 37→      '@openacp/usage': 'usage',
 38→      '@openacp/file-service': 'files',
 39→      '@openacp/api-server': 'api',
 40→      '@openacp/telegram': 'channels.telegram',
 41→      '@openacp/discord': 'channels.discord',
 42→      '@openacp/plugin-discord': 'channels.discord',
 43→      '@openacp/slack': 'channels.slack',
 44→    }
 45→    const legacyKey = legacyMap[pluginName]
 46→    if (legacyKey) {
 47→      const parts = legacyKey.split('.')
 48→      let obj: any = allConfig
 49→      for (const p of parts) obj = obj?.[p]
 50→      if (obj && typeof obj === 'object') return { ...obj }
 51→    }
 52→  } catch {
 53→    // Gracefully degrade — return empty config
 54→  }
 55→  return {}
 56→}
