 58→export interface LifecycleManagerOpts {
 59→  serviceRegistry?: ServiceRegistry
 60→  middlewareChain?: MiddlewareChain
 61→  errorTracker?: ErrorTracker
 62→  eventBus?: EventBus & {
 63→    on(event: string, handler: (...args: unknown[]) => void): void
 64→    off(event: string, handler: (...args: unknown[]) => void): void
 65→    emit(event: string, payload: unknown): void
 66→  }
 67→  storagePath?: string
 68→  sessions?: unknown
 69→  config?: unknown
 70→  core?: unknown
 71→  log?: Logger
 72→  settingsManager?: SettingsManager
 73→  pluginRegistry?: PluginRegistry
 74→}
 75→
 76→export class LifecycleManager {
 77→  readonly serviceRegistry: ServiceRegistry
 78→  readonly middlewareChain: MiddlewareChain
 79→  readonly errorTracker: ErrorTracker
 80→
 81→  private eventBus: LifecycleManagerOpts['eventBus']
 82→  private storagePath: string
 83→  private sessions: unknown
 84→  private config: unknown
 85→  private core: unknown
 86→  private log: Logger | undefined
 87→  private settingsManager: SettingsManager | undefined
 88→  private pluginRegistry: PluginRegistry | undefined
 89→
 90→  private contexts = new Map<string, ReturnType<typeof createPluginContext>>()
 91→  private loadOrder: OpenACPPlugin[] = []
 92→  private _loaded = new Set<string>()
 93→  private _failed = new Set<string>()
 94→
 95→  get loadedPlugins(): string[] {
 96→    return [...this._loaded]
 97→  }
 98→
 99→  get failedPlugins(): string[] {
100→    return [...this._failed]
101→  }
102→
103→  constructor(opts?: LifecycleManagerOpts) {
104→    this.serviceRegistry = opts?.serviceRegistry ?? new ServiceRegistry()
105→    this.middlewareChain = opts?.middlewareChain ?? new MiddlewareChain()
106→    this.errorTracker = opts?.errorTracker ?? new ErrorTracker()
107→    this.eventBus = opts?.eventBus ?? {
108→      on() {},
109→      off() {},
110→      emit() {},
111→    }
112→    this.storagePath = opts?.storagePath ?? '/tmp/openacp-plugins'
113→    this.sessions = opts?.sessions ?? {}
114→    this.config = opts?.config ?? {}
115→    this.core = opts?.core
116→    this.log = opts?.log
117→    this.settingsManager = opts?.settingsManager
118→    this.pluginRegistry = opts?.pluginRegistry
119→  }
120→
121→  private getPluginLogger(pluginName: string): Logger {
122→    if (this.log && typeof (this.log as any).child === 'function') {
123→      return (this.log as any).child({ plugin: pluginName })
124→    }
125→    return this.log ?? { trace() {}, debug() {}, info() {}, warn() {}, error() {}, fatal() {}, child() { return this } } as Logger
126→  }
127→
128→  async boot(plugins: OpenACPPlugin[]): Promise<void> {
129→    // Resolve load order via topological sort.
130→    // resolveLoadOrder will skip plugins whose dependencies are missing entirely
131→    // (not present in the input list). But we also need to handle runtime setup failures.
132→    // Include already-loaded plugins so dependency checks pass for late-booted plugins
133→    // (e.g., dev plugins booted after core plugins).
134→    const newNames = new Set(plugins.map(p => p.name))
135→    const allForResolution = [...this.loadOrder.filter(p => !newNames.has(p.name)), ...plugins]
136→
137→    let sorted: OpenACPPlugin[]
138→    try {
139→      sorted = resolveLoadOrder(allForResolution)
140→    } catch (err) {
141→      // Circular dependency or other fatal error in resolution
142→      // Mark all as failed
143→      for (const p of plugins) {
144→        this._failed.add(p.name)
145→      }
146→      return
147→    }
148→
149→    // Only boot new plugins (already-loaded ones were included just for dependency resolution)
150→    sorted = sorted.filter(p => newNames.has(p.name))
151→
152→    // Append to existing loadOrder (don't overwrite — hot-reload boots single plugins)
153→    for (const p of sorted) {
154→      if (!this.loadOrder.some(existing => existing.name === p.name)) {
155→        this.loadOrder.push(p)
156→      } else {
157→        // Replace in-place (hot-reload case: plugin was unloaded then re-booted)
158→        const idx = this.loadOrder.findIndex(existing => existing.name === p.name)
159→        this.loadOrder[idx] = p
160→      }
161→    }
162→
163→    for (const plugin of sorted) {
164→      // Check if any required dependency failed at runtime
165→      if (plugin.pluginDependencies) {
166→        const depFailed = Object.keys(plugin.pluginDependencies).some(
167→          (dep) => this._failed.has(dep),
168→        )
169→        if (depFailed) {
170→          this._failed.add(plugin.name)
171→          continue
172→        }
173→      }
174→
175→      // Check if disabled in registry
176→      const registryEntry = this.pluginRegistry?.get(plugin.name)
177→      if (registryEntry && registryEntry.enabled === false) {
178→        this.eventBus?.emit('plugin:disabled', { name: plugin.name })
179→        continue
180→      }
181→
182→      // Check version mismatch → migrate
183→      if (registryEntry && plugin.migrate && registryEntry.version !== plugin.version && this.settingsManager) {
184→        try {
185→          const oldSettings = await this.settingsManager.loadSettings(plugin.name)
186→          const pluginLog = this.getPluginLogger(plugin.name)
187→          const migrateCtx: MigrateContext = {
188→            pluginName: plugin.name,
189→            settings: this.settingsManager.createAPI(plugin.name),
190→            log: pluginLog,
191→          }
192→          const newSettings = await plugin.migrate(migrateCtx, oldSettings, registryEntry.version)
193→          if (newSettings && typeof newSettings === 'object') {
194→            await migrateCtx.settings.setAll(newSettings as Record<string, unknown>)
195→          }
196→          this.pluginRegistry!.updateVersion(plugin.name, plugin.version)
197→          await this.pluginRegistry!.save()
198→        } catch (err) {
199→          this.getPluginLogger(plugin.name).warn(`Migration failed, continuing with old settings: ${err}`)
200→        }
201→      }
202→
203→      // Resolve config: prefer settings.json, fallback to legacy
204→      let pluginConfig: Record<string, unknown>
205→      if (this.settingsManager) {
206→        pluginConfig = await this.settingsManager.loadSettings(plugin.name)
207→        if (Object.keys(pluginConfig).length === 0) {
208→          pluginConfig = resolvePluginConfig(plugin.name, this.config)
209→        }
210→      } else {
211→        pluginConfig = resolvePluginConfig(plugin.name, this.config)
212→      }
213→
214→      // Create context for this plugin
215→      const ctx = createPluginContext({
216→        pluginName: plugin.name,
217→        pluginConfig,
218→        permissions: plugin.permissions ?? [],
219→        serviceRegistry: this.serviceRegistry,
220→        middlewareChain: this.middlewareChain,
221→        errorTracker: this.errorTracker,
222→        eventBus: this.eventBus!,
223→        storagePath: `${this.storagePath}/${plugin.name}`,
224→        sessions: this.sessions,
225→        config: this.config,
226→        core: this.core,
227→        log: this.log,
228→      })
229→
230→      try {
231→        await withTimeout(plugin.setup(ctx), SETUP_TIMEOUT_MS, `${plugin.name}.setup()`)
232→        this.contexts.set(plugin.name, ctx)
233→        this._loaded.add(plugin.name)
234→        this.eventBus?.emit('plugin:loaded', { name: plugin.name, version: plugin.version })
235→      } catch (err) {
236→        this._failed.add(plugin.name)
237→        ctx.cleanup()
238→        this.getPluginLogger(plugin.name).error(`setup() failed: ${err}`)
239→        this.eventBus?.emit('plugin:failed', { name: plugin.name, error: String(err) })
240→      }
241→    }
242→  }
243→
244→  async unloadPlugin(name: string): Promise<void> {
245→    if (!this._loaded.has(name)) return
246→
247→    const plugin = this.loadOrder.find(p => p.name === name)
248→
249→    if (plugin?.teardown) {
250→      try {
251→        await withTimeout(plugin.teardown(), TEARDOWN_TIMEOUT_MS, `${name}.teardown()`)
252→      } catch {
253→        // Swallow teardown errors
254→      }
255→    }
256→
257→    const ctx = this.contexts.get(name)
258→    if (ctx) {
259→      ctx.cleanup()
260→      this.contexts.delete(name)
261→    }
262→
263→    this._loaded.delete(name)
264→    this._failed.delete(name)
265→    this.loadOrder = this.loadOrder.filter(p => p.name !== name)
266→
267→    this.eventBus?.emit('plugin:unloaded', { name })
268→  }
269→
270→  async shutdown(): Promise<void> {
271→    // Teardown in reverse load order
272→    const reversed = [...this.loadOrder].reverse()
273→
274→    for (const plugin of reversed) {
275→      if (!this._loaded.has(plugin.name)) continue
276→
277→      if (plugin.teardown) {
278→        try {
279→          await withTimeout(plugin.teardown(), TEARDOWN_TIMEOUT_MS, `${plugin.name}.teardown()`)
280→        } catch {
281→          // Swallow teardown errors — graceful shutdown
282→        }
283→      }
284→
285→      // Clean up the context
286→      const ctx = this.contexts.get(plugin.name)
287→      if (ctx) {
288→        ctx.cleanup()
289→        this.contexts.delete(plugin.name)
290→      }
291→
292→      this.eventBus?.emit('plugin:unloaded', { name: plugin.name })
293→    }
294→
295→    this._loaded.clear()
296→    this.loadOrder = []
297→  }
298→}
