import * as os from "node:os";
import * as path from "node:path";
import * as clack from "@clack/prompts";
import type { Config } from "../config/config.js";
import type { ConfiguredChannelAction, ChannelId, ChannelStatus } from "./types.js";
import { CHANNEL_META } from "./types.js";
import { guardCancel, ok, c } from "./helpers.js";

export function getChannelStatuses(config: Config): ChannelStatus[] {
  const statuses: ChannelStatus[] = [];

  for (const [id, meta] of Object.entries(CHANNEL_META) as [ChannelId, typeof CHANNEL_META[ChannelId]][]) {
    const ch = config.channels[id] as Record<string, unknown> | undefined;
    const enabled = ch?.enabled === true;
    const configured = !!ch && Object.keys(ch).length > 1;

    let hint: string | undefined;
    if (id === "telegram" && ch?.botToken && typeof ch.botToken === "string" && ch.botToken !== "YOUR_BOT_TOKEN_HERE") {
      hint = `Chat ID: ${ch.chatId}`;
    }
    if (id === "discord" && ch?.guildId) {
      hint = `Guild: ${ch.guildId}`;
    }

    statuses.push({ id, label: meta.label, configured, enabled, hint });
  }

  return statuses;
}

export function noteChannelStatus(config: Config): void {
  const statuses = getChannelStatuses(config);
  const lines = statuses.map((s) => {
    const status = s.enabled ? "enabled" : s.configured ? "disabled" : "not configured";
    const hintStr = s.hint ? ` — ${s.hint}` : "";
    return `  ${s.label}: ${status}${hintStr}`;
  });

  console.log("");
  console.log(`${c.bold}  Channel status${c.reset}`);
  for (const line of lines) console.log(line);
  console.log("");
}

async function promptConfiguredAction(label: string): Promise<ConfiguredChannelAction> {
  return guardCancel(
    await clack.select({
      message: `${label} already configured. What do you want to do?`,
      options: [
        { value: "modify" as const, label: "Modify settings" },
        { value: "disable" as const, label: "Disable bot" },
        { value: "delete" as const, label: "Delete config" },
        { value: "skip" as const, label: "Skip (leave as-is)" },
      ],
      initialValue: "modify" as const,
    }),
  );
}

async function configureViaPlugin(channelId: ChannelId): Promise<void> {
  const pluginImports: Record<ChannelId, () => Promise<any>> = {
    telegram: () => import('../../plugins/telegram/index.js'),
    discord: async () => {
      const pkg = '@openacp/plugin-discord';
      try {
        return await import(/* webpackIgnore: true */ pkg);
      } catch {
        throw new Error(
          `${pkg} is not installed. Run: openacp plugin add ${pkg}`,
        );
      }
    },
  };

  const importer = pluginImports[channelId];
  if (!importer) return;

  const { SettingsManager } = await import('../plugin/settings-manager.js');
  const { createInstallContext } = await import('../plugin/install-context.js');
  const basePath = path.join(os.homedir(), '.openacp', 'plugins');
  const settingsManager = new SettingsManager(basePath);

  const pluginModule = await importer();
  const plugin = pluginModule.default;

  if (plugin?.configure) {
    const ctx = createInstallContext({
      pluginName: plugin.name,
      settingsManager,
      basePath,
    });
    await plugin.configure(ctx);
  }
}

export async function configureChannels(config: Config): Promise<{ config: Config; changed: boolean }> {
  const next = structuredClone(config);
  let changed = false;

  noteChannelStatus(next);

  while (true) {
    const statuses = getChannelStatuses(next);
    const options = statuses.map((s) => {
      const status = s.enabled ? "enabled" : s.configured ? "disabled" : "not configured";
      return {
        value: s.id,
        label: `${s.label} (${CHANNEL_META[s.id].method})`,
        hint: status + (s.hint ? ` · ${s.hint}` : ""),
      };
    });

    const choice = guardCancel(
      await clack.select({
        message: "Select a channel",
        options: [
          ...options,
          { value: "__done__" as const, label: "Finished" },
        ],
      }),
    );

    if (choice === "__done__") break;

    const channelId = choice as ChannelId;
    const meta = CHANNEL_META[channelId];
    const existing = next.channels[channelId] as Record<string, unknown> | undefined;
    const isConfigured = !!existing && Object.keys(existing).length > 1;

    if (isConfigured) {
      const action = await promptConfiguredAction(meta.label);

      if (action === "skip") continue;
      if (action === "disable") {
        (next.channels[channelId] as Record<string, unknown>).enabled = false;
        changed = true;
        console.log(ok(`${meta.label} disabled`));
        continue;
      }
      if (action === "delete") {
        const confirmed = guardCancel(
          await clack.confirm({
            message: `Delete ${meta.label} config? This cannot be undone.`,
            initialValue: false,
          }),
        );
        if (confirmed) {
          delete next.channels[channelId];
          changed = true;
          console.log(ok(`${meta.label} config deleted`));
        }
        continue;
      }
      // action === "modify" — fall through to plugin configure
    }

    // Run channel configuration via plugin configure()
    await configureViaPlugin(channelId);
    changed = true;
  }

  return { config: next, changed };
}

import { execSync } from "node:child_process";
import * as path from "node:path";
import * as clack from "@clack/prompts";
import type { Config, ConfigManager } from "../config/config.js";
import type { ChannelId } from "./types.js";
import type { OnboardSection } from "./types.js";
import { ONBOARD_SECTION_OPTIONS } from "./types.js";
import { guardCancel, ok, fail, printStartBanner, summarizeConfig } from "./helpers.js";
import { setupAgents } from "./setup-agents.js";
import { setupWorkspace } from "./setup-workspace.js";
import { setupRunMode } from "./setup-run-mode.js";
import { setupIntegrations } from "./setup-integrations.js";
import { configureChannels } from "./setup-channels.js";
import type { SettingsManager } from "../plugin/settings-manager.js";
import type { PluginRegistry } from "../plugin/plugin-registry.js";

// ─── First-run setup ───

export async function runSetup(
  configManager: ConfigManager,
  opts?: { skipRunMode?: boolean; settingsManager?: SettingsManager; pluginRegistry?: PluginRegistry },
): Promise<boolean> {
  await printStartBanner();
  clack.intro("Let's set up OpenACP");

  const { settingsManager, pluginRegistry } = opts ?? {};

  try {
    if (!settingsManager || !pluginRegistry) {
      console.log(fail('Plugin system not initialized. Cannot set up channels.'));
      return false;
    }

    // Ask user which channels to set up
    const channelChoices = guardCancel(
      await clack.multiselect({
        message: 'Which channels do you want to set up?',
        options: [
          { value: 'telegram' as const, label: 'Telegram', hint: 'built-in' },
          { value: 'discord' as const, label: 'Discord', hint: 'will install @openacp/plugin-discord' },
        ],
        required: true,
        initialValues: ['telegram' as const],
      }),
    ) as ChannelId[];

    // Calculate total steps dynamically: channel(s) + workspace + run mode
    const channelSteps = channelChoices.length;
    const runModeSteps = opts?.skipRunMode ? 0 : 1;
    const totalSteps = channelSteps + 1 + runModeSteps; // + workspace + optional run mode

    let currentStep = 0;

    const { createInstallContext } = await import('../plugin/install-context.js');

    for (const channelId of channelChoices) {
      currentStep++;

      if (channelId === 'telegram') {
        const telegramPlugin = (await import('../../plugins/telegram/index.js')).default;
        const ctx = createInstallContext({
          pluginName: telegramPlugin.name,
          settingsManager,
          basePath: settingsManager.getBasePath(),
        });
        await telegramPlugin.install!(ctx);
        pluginRegistry.register(telegramPlugin.name, {
          version: telegramPlugin.version,
          source: 'builtin',
          enabled: true,
          settingsPath: settingsManager.getSettingsPath(telegramPlugin.name),
          description: telegramPlugin.description,
        });
      }

      if (channelId === 'discord') {
        await installAndSetupDiscord(settingsManager, pluginRegistry);
      }
    }

    const { defaultAgent } = await setupAgents();

    // Offer Claude CLI integration
    await setupIntegrations();

    currentStep++;
    const workspace = await setupWorkspace({ stepNum: currentStep, totalSteps });

    let runMode: 'foreground' | 'daemon' = 'foreground';
    let autoStart = false;
    if (!opts?.skipRunMode) {
      currentStep++;
      const result = await setupRunMode({ stepNum: currentStep, totalSteps });
      runMode = result.runMode;
      autoStart = result.autoStart;
    }

    const security = {
      allowedUserIds: [] as string[],
      maxConcurrentSessions: 20,
      sessionTimeoutMinutes: 60,
    };

    const config: Config = {
      channels: {},
      agents: {},
      defaultAgent,
      workspace,
      security,
      logging: {
        level: "info",
        logDir: "~/.openacp/logs",
        maxFileSize: "10m",
        maxFiles: 7,
        sessionLogRetentionDays: 30,
      },
      runMode,
      autoStart,
      api: {
        port: 21420,
        host: '127.0.0.1',
      },
      sessionStore: { ttlDays: 30 },
      tunnel: {
        enabled: true,
        port: 3100,
        provider: "cloudflare",
        options: {},
        maxUserTunnels: 5,
        storeTtlMinutes: 60,
        auth: { enabled: false },
      },
      usage: {
        enabled: true,
        warningThreshold: 0.8,
        currency: "USD",
        retentionDays: 90,
      },
      integrations: {},
      speech: {
        stt: { provider: null, providers: {} },
        tts: { provider: null, providers: {} },
      },
    };

    try {
      await configManager.writeNew(config);
    } catch (writeErr) {
      console.log(
        fail(`Could not save config: ${(writeErr as Error).message}`),
      );
      return false;
    }

    // Auto-register remaining built-in plugins in the registry
    if (settingsManager && pluginRegistry) {
      await registerBuiltinPlugins(settingsManager, pluginRegistry);
      await pluginRegistry.save();
    }

    clack.outro(`Config saved to ${configManager.getConfigPath()}`);

    if (!opts?.skipRunMode) {
      console.log(ok("Starting OpenACP..."));
      console.log("");
    }

    return true;
  } catch (err) {
    if ((err as Error).name === "ExitPromptError") {
      clack.cancel("Setup cancelled.");
      return false;
    }
    throw err;
  }
}

/**
 * Install @openacp/plugin-discord from npm if needed, then run its install() hook.
 */
async function installAndSetupDiscord(
  settingsManager: SettingsManager,
  pluginRegistry: PluginRegistry,
): Promise<void> {
  const packageName = '@openacp/plugin-discord';

  // Try to import first — if not installed, install it
  let discordPlugin: any;
  try {
    discordPlugin = (await import(packageName)).default;
  } catch {
    const spinner = clack.spinner();
    spinner.start(`Installing ${packageName}...`);
    try {
      const pluginsDir = path.join(settingsManager.getBasePath(), 'plugins');
      execSync(`npm install ${packageName}`, {
        cwd: pluginsDir,
        stdio: 'pipe',
      });
      discordPlugin = (await import(packageName)).default;
      spinner.stop(ok(`${packageName} installed`));
    } catch (installErr) {
      spinner.stop(fail(`Failed to install ${packageName}: ${(installErr as Error).message}`));
      console.log(fail('You can install it later with: openacp plugin add @openacp/plugin-discord'));
      return;
    }
  }

  const { createInstallContext } = await import('../plugin/install-context.js');
  const ctx = createInstallContext({
    pluginName: discordPlugin.name,
    settingsManager,
    basePath: settingsManager.getBasePath(),
  });

  if (discordPlugin.install) {
    await discordPlugin.install(ctx);
  }

  pluginRegistry.register(discordPlugin.name, {
    version: discordPlugin.version,
    source: 'npm',
    enabled: true,
    settingsPath: settingsManager.getSettingsPath(discordPlugin.name),
    description: discordPlugin.description,
  });
}

/**
 * Register all built-in plugins that haven't been registered yet.
 * Called after first-run setup to populate the registry with defaults.
 */
async function registerBuiltinPlugins(
  settingsManager: SettingsManager,
  pluginRegistry: PluginRegistry,
): Promise<void> {
  const builtinPlugins = [
    { name: '@openacp/security', version: '1.0.0', description: 'User access control and session limits' },
    { name: '@openacp/file-service', version: '1.0.0', description: 'File storage and management' },
    { name: '@openacp/context', version: '1.0.0', description: 'Conversation context management' },
    { name: '@openacp/usage', version: '1.0.0', description: 'Token usage tracking and budget enforcement' },
    { name: '@openacp/speech', version: '1.0.0', description: 'Text-to-speech and speech-to-text' },
    { name: '@openacp/notifications', version: '1.0.0', description: 'Cross-session notification routing' },
    { name: '@openacp/tunnel', version: '1.0.0', description: 'Expose local services via tunnel' },
    { name: '@openacp/api-server', version: '1.0.0', description: 'REST API + SSE streaming server' },
  ];

  for (const p of builtinPlugins) {
    if (!pluginRegistry.get(p.name)) {
      pluginRegistry.register(p.name, {
        version: p.version,
        source: 'builtin',
        enabled: true,
        settingsPath: settingsManager.getSettingsPath(p.name),
        description: p.description,
      });
    }
  }
}

// ─── Reconfigure (section-based, for existing config) ───

type ReconfigureSection = OnboardSection | "__continue";

async function selectSection(hasSelection: boolean): Promise<ReconfigureSection> {
  return guardCancel(
    await clack.select({
      message: "Select sections to configure",
      options: [
        ...ONBOARD_SECTION_OPTIONS,
        {
          value: "__continue" as const,
          label: "Continue",
          hint: hasSelection ? "Done" : "Skip for now",
        },
      ],
      initialValue: ONBOARD_SECTION_OPTIONS[0].value,
    }),
  ) as ReconfigureSection;
}

export async function runReconfigure(configManager: ConfigManager): Promise<void> {
  await printStartBanner();
  clack.intro("OpenACP — Reconfigure");

  try {
    await configManager.load();
    let config = configManager.get();

    // Show current config summary
    clack.note(summarizeConfig(config), "Current configuration");

    let ranSection = false;

    while (true) {
      const choice = await selectSection(ranSection);
      if (choice === "__continue") break;
      ranSection = true;

      if (choice === "channels") {
        const result = await configureChannels(config);
        if (result.changed) {
          // IMPORTANT: Use writeNew() instead of save() because save() uses deepMerge
          // which cannot delete keys. Channel deletion (delete next.channels.telegram)
          // would be silently ignored by deepMerge. writeNew() overwrites the full config.
          config = { ...config, channels: result.config.channels };
          await configManager.writeNew(config);
        }
      }

      if (choice === "agents") {
        const { defaultAgent } = await setupAgents();
        await configManager.save({ defaultAgent });
        config = configManager.get();
      }

      if (choice === "workspace") {
        const { baseDir } = await setupWorkspace({
          existing: config.workspace.baseDir,
        });
        await configManager.save({ workspace: { baseDir } });
        config = configManager.get();
      }

      if (choice === "runMode") {
        const result = await setupRunMode({
          existing: { runMode: config.runMode, autoStart: config.autoStart },
        });
        await configManager.save({
          runMode: result.runMode,
          autoStart: result.autoStart,
        });
        config = configManager.get();
      }

      if (choice === "integrations") {
        await setupIntegrations(config);
      }
    }

    if (!ranSection) {
      clack.outro("No changes made.");
      return;
    }

    clack.outro(`Config saved to ${configManager.getConfigPath()}`);
  } catch (err) {
    if ((err as Error).name === "ExitPromptError") {
      clack.cancel("Setup cancelled.");
      return;
    }
    throw err;
  }
}

import { resolveLoadOrder } from './plugin-loader.js'
import { ServiceRegistry } from './service-registry.js'
import { MiddlewareChain } from './middleware-chain.js'
import { ErrorTracker } from './error-tracker.js'
import { createPluginContext } from './plugin-context.js'
import type { OpenACPPlugin, EventBus, Logger, MigrateContext } from './types.js'
import type { SettingsManager } from './settings-manager.js'
import type { PluginRegistry } from './plugin-registry.js'

const SETUP_TIMEOUT_MS = 30_000
const TEARDOWN_TIMEOUT_MS = 10_000

function withTimeout<T>(promise: Promise<T>, ms: number, label: string): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`Timeout: ${label} exceeded ${ms}ms`)), ms)
    if (typeof timer === 'object' && timer !== null && 'unref' in timer) {
      ;(timer as NodeJS.Timeout).unref()
    }
    promise.then(resolve, reject).finally(() => clearTimeout(timer))
  })
}

function resolvePluginConfig(pluginName: string, configManager: unknown): Record<string, unknown> {
  try {
    const allConfig = (configManager as any)?.get?.() ?? {}
    // Try new format: plugins.builtin['@openacp/speech'].config
    const pluginEntry = allConfig.plugins?.builtin?.[pluginName]
    if (pluginEntry?.config && Object.keys(pluginEntry.config).length > 0) {
      return pluginEntry.config
    }
    // @deprecated Legacy config path mapping — kept for backward compat with pre-plugin configs.
    // New plugins should use plugins.builtin['<name>'].config format. Remove when all users have migrated.
    const legacyMap: Record<string, string> = {
      '@openacp/security': 'security',
      '@openacp/speech': 'speech',
      '@openacp/tunnel': 'tunnel',
      '@openacp/usage': 'usage',
      '@openacp/file-service': 'files',
      '@openacp/api-server': 'api',
      '@openacp/telegram': 'channels.telegram',
      '@openacp/discord': 'channels.discord',
      '@openacp/plugin-discord': 'channels.discord',
      '@openacp/slack': 'channels.slack',
    }
    const legacyKey = legacyMap[pluginName]
    if (legacyKey) {
      const parts = legacyKey.split('.')
      let obj: any = allConfig
      for (const p of parts) obj = obj?.[p]
      if (obj && typeof obj === 'object') return { ...obj }
    }
  } catch {
    // Gracefully degrade — return empty config
  }
  return {}
}

export interface LifecycleManagerOpts {
  serviceRegistry?: ServiceRegistry
  middlewareChain?: MiddlewareChain
  errorTracker?: ErrorTracker
  eventBus?: EventBus & {
    on(event: string, handler: (...args: unknown[]) => void): void
    off(event: string, handler: (...args: unknown[]) => void): void
    emit(event: string, payload: unknown): void
  }
  storagePath?: string
  sessions?: unknown
  config?: unknown
  core?: unknown
  log?: Logger
  settingsManager?: SettingsManager
  pluginRegistry?: PluginRegistry
}

export class LifecycleManager {
  readonly serviceRegistry: ServiceRegistry
  readonly middlewareChain: MiddlewareChain
  readonly errorTracker: ErrorTracker

  private eventBus: LifecycleManagerOpts['eventBus']
  private storagePath: string
  private sessions: unknown
  private config: unknown
  private core: unknown
  private log: Logger | undefined
  private settingsManager: SettingsManager | undefined
  private pluginRegistry: PluginRegistry | undefined

  private contexts = new Map<string, ReturnType<typeof createPluginContext>>()
  private loadOrder: OpenACPPlugin[] = []
  private _loaded = new Set<string>()
  private _failed = new Set<string>()

  get loadedPlugins(): string[] {
    return [...this._loaded]
  }

  get failedPlugins(): string[] {
    return [...this._failed]
  }

  constructor(opts?: LifecycleManagerOpts) {
    this.serviceRegistry = opts?.serviceRegistry ?? new ServiceRegistry()
    this.middlewareChain = opts?.middlewareChain ?? new MiddlewareChain()
    this.errorTracker = opts?.errorTracker ?? new ErrorTracker()
    this.eventBus = opts?.eventBus ?? {
      on() {},
      off() {},
      emit() {},
    }
    this.storagePath = opts?.storagePath ?? '/tmp/openacp-plugins'
    this.sessions = opts?.sessions ?? {}
    this.config = opts?.config ?? {}
    this.core = opts?.core
    this.log = opts?.log
    this.settingsManager = opts?.settingsManager
    this.pluginRegistry = opts?.pluginRegistry
  }

  private getPluginLogger(pluginName: string): Logger {
    if (this.log && typeof (this.log as any).child === 'function') {
      return (this.log as any).child({ plugin: pluginName })
    }
    return this.log ?? { trace() {}, debug() {}, info() {}, warn() {}, error() {}, fatal() {}, child() { return this } } as Logger
  }

  async boot(plugins: OpenACPPlugin[]): Promise<void> {
    // Resolve load order via topological sort.
    // resolveLoadOrder will skip plugins whose dependencies are missing entirely
    // (not present in the input list). But we also need to handle runtime setup failures.
    // Include already-loaded plugins so dependency checks pass for late-booted plugins
    // (e.g., dev plugins booted after core plugins).
    const newNames = new Set(plugins.map(p => p.name))
    const allForResolution = [...this.loadOrder.filter(p => !newNames.has(p.name)), ...plugins]

    let sorted: OpenACPPlugin[]
    try {
      sorted = resolveLoadOrder(allForResolution)
    } catch (err) {
      // Circular dependency or other fatal error in resolution
      // Mark all as failed
      for (const p of plugins) {
        this._failed.add(p.name)
      }
      return
    }

    // Only boot new plugins (already-loaded ones were included just for dependency resolution)
    sorted = sorted.filter(p => newNames.has(p.name))

    // Append to existing loadOrder (don't overwrite — hot-reload boots single plugins)
    for (const p of sorted) {
      if (!this.loadOrder.some(existing => existing.name === p.name)) {
        this.loadOrder.push(p)
      } else {
        // Replace in-place (hot-reload case: plugin was unloaded then re-booted)
        const idx = this.loadOrder.findIndex(existing => existing.name === p.name)
        this.loadOrder[idx] = p
      }
    }

    for (const plugin of sorted) {
      // Check if any required dependency failed at runtime
      if (plugin.pluginDependencies) {
        const depFailed = Object.keys(plugin.pluginDependencies).some(
          (dep) => this._failed.has(dep),
        )
        if (depFailed) {
          this._failed.add(plugin.name)
          continue
        }
      }

      // Check if disabled in registry
      const registryEntry = this.pluginRegistry?.get(plugin.name)
      if (registryEntry && registryEntry.enabled === false) {
        this.eventBus?.emit('plugin:disabled', { name: plugin.name })
        continue
      }

      // Check version mismatch → migrate
      if (registryEntry && plugin.migrate && registryEntry.version !== plugin.version && this.settingsManager) {
        try {
          const oldSettings = await this.settingsManager.loadSettings(plugin.name)
          const pluginLog = this.getPluginLogger(plugin.name)
          const migrateCtx: MigrateContext = {
            pluginName: plugin.name,
            settings: this.settingsManager.createAPI(plugin.name),
            log: pluginLog,
          }
          const newSettings = await plugin.migrate(migrateCtx, oldSettings, registryEntry.version)
          if (newSettings && typeof newSettings === 'object') {
            await migrateCtx.settings.setAll(newSettings as Record<string, unknown>)
          }
          this.pluginRegistry!.updateVersion(plugin.name, plugin.version)
          await this.pluginRegistry!.save()
        } catch (err) {
          this.getPluginLogger(plugin.name).warn(`Migration failed, continuing with old settings: ${err}`)
        }
      }

      // Resolve config: prefer settings.json, fallback to legacy
      let pluginConfig: Record<string, unknown>
      if (this.settingsManager) {
        pluginConfig = await this.settingsManager.loadSettings(plugin.name)
        if (Object.keys(pluginConfig).length === 0) {
          pluginConfig = resolvePluginConfig(plugin.name, this.config)
        }
      } else {
        pluginConfig = resolvePluginConfig(plugin.name, this.config)
      }

      // Create context for this plugin
      const ctx = createPluginContext({
        pluginName: plugin.name,
        pluginConfig,
        permissions: plugin.permissions ?? [],
        serviceRegistry: this.serviceRegistry,
        middlewareChain: this.middlewareChain,
        errorTracker: this.errorTracker,
        eventBus: this.eventBus!,
        storagePath: `${this.storagePath}/${plugin.name}`,
        sessions: this.sessions,
        config: this.config,
        core: this.core,
        log: this.log,
      })

      try {
        await withTimeout(plugin.setup(ctx), SETUP_TIMEOUT_MS, `${plugin.name}.setup()`)
        this.contexts.set(plugin.name, ctx)
        this._loaded.add(plugin.name)
        this.eventBus?.emit('plugin:loaded', { name: plugin.name, version: plugin.version })
      } catch (err) {
        this._failed.add(plugin.name)
        ctx.cleanup()
        this.getPluginLogger(plugin.name).error(`setup() failed: ${err}`)
        this.eventBus?.emit('plugin:failed', { name: plugin.name, error: String(err) })
      }
    }
  }

  async unloadPlugin(name: string): Promise<void> {
    if (!this._loaded.has(name)) return

    const plugin = this.loadOrder.find(p => p.name === name)

    if (plugin?.teardown) {
      try {
        await withTimeout(plugin.teardown(), TEARDOWN_TIMEOUT_MS, `${name}.teardown()`)
      } catch {
        // Swallow teardown errors
      }
    }

    const ctx = this.contexts.get(name)
    if (ctx) {
      ctx.cleanup()
      this.contexts.delete(name)
    }

    this._loaded.delete(name)
    this._failed.delete(name)
    this.loadOrder = this.loadOrder.filter(p => p.name !== name)

    this.eventBus?.emit('plugin:unloaded', { name })
  }

  async shutdown(): Promise<void> {
    // Teardown in reverse load order
    const reversed = [...this.loadOrder].reverse()

    for (const plugin of reversed) {
      if (!this._loaded.has(plugin.name)) continue

      if (plugin.teardown) {
        try {
          await withTimeout(plugin.teardown(), TEARDOWN_TIMEOUT_MS, `${plugin.name}.teardown()`)
        } catch {
          // Swallow teardown errors — graceful shutdown
        }
      }

      // Clean up the context
      const ctx = this.contexts.get(plugin.name)
      if (ctx) {
        ctx.cleanup()
        this.contexts.delete(plugin.name)
      }

      this.eventBus?.emit('plugin:unloaded', { name: plugin.name })
    }

    this._loaded.clear()
    this.loadOrder = []
  }
}

